function getEntriesByDotNotation(options, path) {
  // Split the path into parts based on '.'
  const parts = path.split('.');

  // Use Object.entries() to create an array of [key, value] pairs for each level
  let currentLevel = options;
  for (let i = 0; i < parts.length - 1; i++) {
    currentLevel = currentLevel[parts[i]];
  }

  // Return the values of the properties at the last index of the split path
  return currentLevel[parts[parts.length - 1]] || [];
}

